python - <<'PY'
import openpyxl, re, math
from pathlib import Path
src_path = Path('/root/copy_of_capacity_sheet.xlsx')
wb = openpyxl.load_workbook(src_path, data_only=True)
print('sheets:', wb.sheetnames)
ws = wb['Weld']
# find the row containing label
label = 'MIG weld Demand Total'
label_cell = None
for row in ws.iter_rows(values_only=False):
    for cell in row:
        v = cell.value
        if isinstance(v,str) and v.strip() == label:
            label_cell = cell
            break
    if label_cell:
        break
print('label_cell:', label_cell.coordinate if label_cell else None)
if not label_cell:
    raise SystemExit('Label not found')
demand_row = label_cell.row
label_col = label_cell.column
# gather candidate header rows above demand_row (up to 15 rows)
candidate_rows = list(range(max(1, demand_row-20), demand_row))
# function to extract week number from cell
week_pat = re.compile(r'\b(?:wk|week)\s*(\d{1,2})\b', re.I)

def parse_week(val):
    if val is None:
        return None
    if isinstance(val, (int, float)) and float(val).is_integer():
        n = int(val)
        if 1 <= n <= 53:
            return n
    if isinstance(val, str):
        s = val.strip()
        m = week_pat.search(s)
        if m:
            n = int(m.group(1))
            if 1 <= n <= 53:
                return n
        # also match bare numbers in strings
        if re.fullmatch(r'\d{1,2}', s):
            n = int(s)
            if 1 <= n <= 53:
                return n
    return None

# score rows by how many distinct weeks they contain
row_scores = []
max_col = ws.max_column
for r in candidate_rows:
    weeks = {}
    for c in range(1, max_col+1):
        w = parse_week(ws.cell(r,c).value)
        if w is not None:
            weeks.setdefault(w, []).append(c)
    score = len(weeks)
    if score:
        row_scores.append((score, r, weeks))
row_scores.sort(reverse=True)
print('top header row candidates (score,row):', [(s,r) for s,r,_ in row_scores[:5]])
if not row_scores:
    raise SystemExit('No header rows with week labels found')
# pick best row; if tie, pick closest to demand_row
best_score = row_scores[0][0]
bests = [t for t in row_scores if t[0]==best_score]
bests.sort(key=lambda t: abs(t[1]-demand_row))
_, header_row, weeks_map = bests[0]
print('chosen header_row:', header_row, 'score:', best_score)
# build week->column mapping; if week label repeated, choose leftmost
week_to_col = {w: min(cols) for w, cols in weeks_map.items()}
missing = [w for w in range(4,53) if w not in week_to_col]
print('missing weeks from chosen row:', missing[:10], 'count', len(missing))
# If missing, try multi-row header by searching down from header_row to demand_row-1
if missing:
    # search each missing week in any candidate row; choose first found column
    for w in missing:
        found = None
        for r in range(header_row, demand_row):
            for c in range(1, max_col+1):
                if parse_week(ws.cell(r,c).value) == w:
                    found = c
                    break
            if found:
                break
        if found:
            week_to_col[w] = found
    missing2 = [w for w in range(4,53) if w not in week_to_col]
    print('missing after multi-row search:', missing2[:10], 'count', len(missing2))
    if missing2:
        # as last resort, try identify a starting column by finding week4 and then assume consecutive columns
        if 4 in week_to_col:
            start_col = week_to_col[4]
            for i,w in enumerate(range(4,53)):
                week_to_col.setdefault(w, start_col+i)
        missing3 = [w for w in range(4,53) if w not in week_to_col]
        print('missing after consecutive fill:', missing3[:10], 'count', len(missing3))

# extract demand values
weeks = list(range(4,53))
demands = []
for w in weeks:
    c = week_to_col[w]
    v = ws.cell(demand_row, c).value
    demands.append(v)
print('demand row', demand_row)
print('week4 col', openpyxl.utils.get_column_letter(week_to_col[4]), week_to_col[4])
# print demands
for w,v in zip(weeks,demands):
    print(f'Week {w}: {v}')
